export function LoadingState({
  label = "{{label}}",
  accent = "{{accent}}",
  force = {{force}},
  radius = {{radius}},
}) {
  return (
    <>
      <button type="button" disabled={force} aria-busy={force}
        style={{ display: "inline-flex", alignItems: "center", gap: 9, font: "700 15px system-ui, sans-serif", padding: "11px 22px", borderRadius: radius, border: `2px solid ${accent}`, background: accent, color: "#241430", cursor: force ? "not-allowed" : "pointer", opacity: force ? 0.8 : 1 }}>
        {force && (
          <span aria-hidden="true" className="loading-spinner" style={{ width: 14, height: 14, borderRadius: "50%", border: "2.5px solid #24143040", borderTopColor: "#241430" }} />
        )}
        <span>{force ? "Saving…" : label}</span>
      </button>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .loading-spinner { animation: ld-spin .7s linear infinite; }
          @keyframes ld-spin { to { transform: rotate(360deg); } }
        }
      `}</style>
    </>
  );
}
